from ub import *
UNIT = mkunit("u110",
 ["memakai **huruf kapital** pada awal kalimat, nama, hari, bulan, dan bahasa",
  "memakai **titik, tanda tanya, dan tanda seru** dengan benar",
  "memakai **koma** pada daftar, kalimat majemuk, dan salam",
  "memakai **apostrof** untuk singkatan dan kepemilikan, serta tanda kutip"],
 [intro("Tanda baca membuat tulisan mudah dipahami. Dalam bahasa Inggris, huruf kapital dan tanda baca punya aturan yang sedikit berbeda dengan bahasa Indonesia. Kuasai aturan dasar berikut agar tulisanmu rapi."),
  gram("1. Huruf kapital",
   table=[["Pakai huruf kapital untuk", "Contoh"],
          ["Awal kalimat", "[[The class starts at eight.]]"],
          ["Kata ganti **I**", "[[Today I am happy.]]"],
          ["Nama orang dan tempat", "[[Rani lives in Bandung.]]"],
          ["Hari, bulan, hari libur", "[[Monday]], [[May]], [[Independence Day]]"],
          ["Negara, bahasa, kebangsaan", "[[Indonesia]], [[English]], [[Japanese]]"],
          ["Gelar sebelum nama", "[[Mr. Adi]], [[Dr. Sari]]"]],
   examples=[("[[On Monday, I speak English with Mr. Adi in Jakarta.]]", "Hari Senin, aku berbicara bahasa Inggris dengan Pak Adi di Jakarta.")]),
  gram("2. Titik, tanda tanya, tanda seru",
   table=[["Tanda", "Dipakai untuk", "Contoh"],
          ["**.** titik", "pernyataan biasa", "[[I like tea.]]"],
          ["**?** tanda tanya", "pertanyaan langsung", "[[Where do you live?]]"],
          ["**!** tanda seru", "perasaan kuat / perintah keras", "[[What a nice day!]] / [[Stop!]]"]],
   examples=[("[[Do you like tea? Yes, I do.]]", "Apakah kamu suka teh? Ya, suka.")]),
  gram("3. Koma",
   table=[["Aturan", "Contoh"],
          ["Memisahkan daftar (3 hal atau lebih)", "[[I bought apples, oranges, and bananas.]]"],
          ["Sebelum and/but/so pada dua klausa utuh", "[[I was tired, but I finished the work.]]"],
          ["Setelah kata pembuka", "[[However, it was too late.]] / [[First, wash your hands.]]"],
          ["Setelah klausa pembuka (if, when, although)", "[[When it rains, we stay home.]]"],
          ["Memanggil nama", "[[Rani, come here.]]"],
          ["Setelah salam pada surat santai", "[[Dear Budi,]]"]]),
  gram("4. Apostrof dan tanda kutip",
   table=[["Tanda", "Fungsi", "Contoh"],
          ["**'** apostrof", "singkatan", "[[don't]] (do not), [[I'm]] (I am), [[it's]] (it is)"],
          ["**'s** apostrof", "milik (orang/benda tunggal)", "[[Rani's bag]], [[the dog's tail]]"],
          ["**s'** apostrof", "milik (jamak berakhir s)", "[[the students' books]]"],
          ["**\" \"** tanda kutip", "ucapan langsung", "[[She said, \"I am ready.\"]]"]]),
  warn("Apostrof bukan untuk jamak", text="Salah: *two cat's*. Benar: [[two cats]]. Apostrof hanya untuk singkatan atau kepemilikan."),
  tip("Baca keras-keras", text="Tempat jeda alami saat membaca keras sering menunjukkan di mana koma dibutuhkan. Titik adalah akhir pikiran yang lengkap."),
  summary(["Kapital: awal kalimat, I, nama, hari, bulan, bahasa, negara.", "Titik, ?, ! di akhir kalimat.", "Koma: daftar, setelah kata pembuka, sebelum and/but pada dua klausa.", "Apostrof: singkatan dan kepemilikan, bukan jamak."])],
 [], [])
